def strategy(history, rng):
    n = len(history)
    if n >= 99:
        return 'D'
    if n == 0:
        return 'C'

    me = [h[0] for h in history]
    opp = [h[1] for h in history]
    my_last = me[-1]
    opp_last = opp[-1]

    opp_d_total = 0
    my_d_total = 0
    for i in range(n):
        if opp[i] == 'D':
            opp_d_total += 1
        if me[i] == 'D':
            my_d_total += 1

    opp_streak = 0
    idx = n - 1
    while idx >= 0 and opp[idx] == 'D':
        opp_streak += 1
        idx -= 1

    recent_len = n if n < 8 else 8
    recent_start = n - recent_len
    recent_opp_d = 0
    for i in range(recent_start, n):
        if opp[i] == 'D':
            recent_opp_d += 1

    c_obs = 0
    c_pun = 0
    d_obs = 0
    d_pun = 0
    for i in range(n - 1):
        if me[i] == 'C':
            c_obs += 1
            if opp[i + 1] == 'D':
                c_pun += 1
        else:
            d_obs += 1
            if opp[i + 1] == 'D':
                d_pun += 1

    start = n - 14
    if start < 0:
        start = 0
    rc_obs = 0
    rc_pun = 0
    rd_obs = 0
    rd_pun = 0
    for i in range(start, n - 1):
        if me[i] == 'C':
            rc_obs += 1
            if opp[i + 1] == 'D':
                rc_pun += 1
        else:
            rd_obs += 1
            if opp[i + 1] == 'D':
                rd_pun += 1

    c_rate = (c_pun + 1.0) / (c_obs + 2.0)
    d_rate = (d_pun + 1.0) / (d_obs + 2.0)

    if rc_obs >= 3:
        c_eff = (rc_pun + 1.0) / (rc_obs + 2.0)
    else:
        c_eff = c_rate

    if rd_obs >= 3:
        d_eff = (rd_pun + 1.0) / (rd_obs + 2.0)
    else:
        d_eff = d_rate

    high_defector = False
    if n >= 2 and opp_d_total == n:
        high_defector = True
    if n >= 10 and opp_d_total * 4 >= n * 3:
        high_defector = True
    if recent_len >= 6 and recent_opp_d * 4 >= recent_len * 3:
        high_defector = True
    if opp_streak >= 4:
        high_defector = True
    if c_obs >= 6 and c_pun * 4 >= c_obs * 3:
        high_defector = True
    if c_eff > 0.70 and d_eff > 0.55 and c_obs >= 5:
        high_defector = True
    if opp_d_total >= max(4, (2 * n) // 3) and recent_opp_d >= max(3, recent_len // 2):
        high_defector = True
    if n >= 8 and c_obs >= 5 and c_eff >= 0.35:
        if d_obs < 3 or d_eff <= c_eff + 0.30:
            high_defector = True

    if high_defector:
        return 'D'

    exploitable = False
    if d_obs >= 1:
        if d_pun == 0 and c_pun == 0:
            exploitable = True

    if d_obs >= 2 and c_obs >= 4:
        if d_rate <= c_rate + 0.25 and d_rate < 0.70:
            exploitable = True

    if d_obs >= 3:
        if d_rate < 0.45 and c_rate < 0.70:
            exploitable = True
        if d_eff <= c_eff + 0.25 and d_eff < 0.70:
            exploitable = True

    if not exploitable and n >= 12 and opp_d_total <= 3 and my_d_total >= 2 and d_pun == 0:
        exploitable = True

    if opp_last == 'D':
        if my_last == 'C':
            if opp_streak >= 2:
                return 'D'
            if recent_len >= 4 and recent_opp_d >= recent_len - 1:
                return 'D'
            if opp_d_total > (n + 2) // 3 and recent_opp_d >= 2:
                return 'D'
            if c_eff > 0.60:
                return 'D'
            return 'C'
        else:
            if opp_d_total == n or opp_streak >= 3:
                return 'D'
            if recent_len >= 4 and recent_opp_d >= recent_len - 1:
                return 'D'
            if exploitable and c_rate >= 0.30 and d_rate <= c_rate + 0.35:
                return 'D'
            return 'C'

    if exploitable:
        return 'D'

    if my_last == 'D':
        if d_obs >= 2 and d_rate < 0.40 and c_rate < 0.40:
            return 'D'
        return 'C'

    if n == 4:
        if opp_d_total <= 1 and c_rate < 0.65:
            return 'D'

    if n == 20 or n == 40 or n == 60 or n == 80:
        if opp_d_total <= max(3, n // 4) and c_eff < 0.35 and recent_opp_d <= 2:
            if d_obs == 0 or d_eff > 0.55:
                return 'D'

    if n >= 30 and n % 30 == 0:
        if opp_d_total == 0 and c_rate < 0.15:
            return 'D'

    return 'C'
